mapper.select:
SELECT cpl.`id`, cpl.`name`, cpl.`camera_num`, cpl.`patrol_num`, COALESCE(sum(cpr.`abnormal_num`),0) as abnormal_num, GROUP_CONCAT(DISTINCT cpr.user_name) as patrol_user_names FROM `camera_patrol_line` cpl LEFT JOIN `camera_patrol_record` cpr on cpl.`id` = cpr.`camera_patrol_line_id`
and cpl.`name` like concat('%',#{param.keyword},'%')
and cpr.`patrol_time` >= #{param.period.begin}
and cpr.`patrol_time` <= #{param.period.end}
GROUP BY cpl.`id`

