SELECT cpl.`id`, cpl.`name`, COALESCE(sum(cpr.`abnormal_num`),0) as total_num FROM `camera_patrol_line` cpl LEFT JOIN `camera_patrol_record` cpr on cpl.id = cpr.camera_patrol_line_id
and cpr.`patrol_time` >= #{param.period.begin}
and cpr.`patrol_time` <= #{param.period.end}
GROUP BY cpl.`id`

SELECT cpl.`id`, cpl.`name`, COALESCE(sum(cpr.`abnormal_num`),0) as total_num FROM `camera_patrol_line` cpl INNER JOIN `camera_patrol_record` cpr on cpl.`id` = cpr.`camera_patrol_line_id` and `abnormal_num` > 0
and cpr.`patrol_time` >= #{param.period.begin}
and cpr.`patrol_time` <= #{param.period.end}
GROUP BY cpl.`id`

SELECT
COUNT(1) as total_num
FROM
`camera_patrol_line`


        and `enabled` = #{param.enabled}


        and `create_time` >= #{param.period.begin}


        and `create_time` <= #{param.period.end}

SELECT
COUNT(DISTINCT t2.`device_id`) as total_num
FROM
`camera_patrol_line` t1
INNER JOIN `camera_patrol_device` t2 on t1.`id` = t2.`camera_patrol_line_id`


        and t1.`enabled` = #{param.enabled}


        and t1.`create_time` >= #{param.period.begin}


        and t1.`create_time` <= #{param.period.end}
